  'business-analytics-data-analysis',
  null,
  'Business Analytics / Data Analysis',
  'Business Analytics / Data Analysis',
  'This course prepares students to turn business questions into data-driven decisions. Students learn the full analytics workflow: problem framing, data literacy, cleaning, spreadsheet modeling, SQL and BI foundations, exploratory analysis, visualization, statistical inference, regression, forecasting, experimentation, optimization, simulation, machine learning basics, supply-chain applications, ethics, governance, and executive communication. The course culminates in an applied analytics project that produces a defensible recommendation for a real business decision.',
  $badajson${"slug": "business-analytics-data-analysis", "title": "Business Analytics / Data Analysis", "description": "This course prepares students to turn business questions into data-driven decisions. Students learn the full analytics workflow: problem framing, data literacy, cleaning, spreadsheet modeling, SQL and BI foundations, exploratory analysis, visualization, statistical inference, regression, forecasting, experimentation, optimization, simulation, machine learning basics, supply-chain applications, ethics, governance, and executive communication. The course culminates in an applied analytics project that produces a defensible recommendation for a real business decision.", "topics": [{"id": "d63b9631-577d-4967-a301-792c9ae9d4a9", "type": "topic", "title": "Analytics Mindset and Business Value Creation", "description": "Students start by learning that analytics is not just software; it is the disciplined conversion of business questions, data, models, and judgment into better decisions.", "children": [{"id": "8277a379-76a4-4a1a-ba5f-2aeb4ebfdd75", "type": "subtopic", "title": "Analytics problem framing", "children": [{"id": "1441a26a-abbe-4354-a653-40e7beb7194a", "type": "concept", "title": "Decision owner and decision cadence"}, {"id": "60f24d5c-98e5-4f48-b7ad-6d6decdb1bcd", "type": "concept", "title": "Business objective, constraints, and success metrics"}, {"id": "f66fae30-e77e-473d-a124-2851dadc265a", "type": "concept", "title": "Descriptive, diagnostic, predictive, and prescriptive questions"}], "description": "The point is to define the business decision before touching the dataset."}, {"id": "65ec9930-fb9a-4841-acec-971826be62b6", "type": "subtopic", "title": "Analytics value chain", "children": [{"id": "dfc00418-ebd7-4b76-a995-4f05b21c5a5e", "type": "concept", "title": "Data generation and collection"}, {"id": "12254e47-9911-44fa-9ada-05324b508bfe", "type": "concept", "title": "Analysis and interpretation"}, {"id": "8c237f96-8c06-4f98-9000-b3ceaf894a41", "type": "concept", "title": "Decision adoption and feedback loops"}], "description": "Students see how raw data becomes insight, recommendation, action, and measured impact."}, {"id": "5322fdf9-90cb-4573-9a6c-589fb28427ac", "type": "subtopic", "title": "Analytics strategy and competitive advantage", "children": [{"id": "0bfc2bc1-5bee-4ba5-8325-cc072fb6c9fc", "type": "concept", "title": "Competing on analytics"}, {"id": "da05172f-f99f-41de-b1d1-3a0b5dadc655", "type": "concept", "title": "Analytics maturity and capability building"}, {"id": "802f2400-bde1-44fa-978e-33ed82d9869c", "type": "concept", "title": "Supply chain, customer, finance, and operations use cases"}], "description": "The gist is to connect analytics capabilities to operating performance and strategy."}]}, {"id": "28ca40c3-5176-4992-970b-85c6dc548c4d", "type": "topic", "title": "Data Literacy, Data Types, and Measurement", "description": "This unit builds the vocabulary needed to reason clearly about variables, tables, events, entities, samples, and business metrics.", "children": [{"id": "592d6bc1-1701-455a-a460-c98b0c14bbcc", "type": "subtopic", "title": "Data types and structures", "children": [{"id": "f851fcc6-7b3d-448b-9cd9-9483dc5d06de", "type": "concept", "title": "Numeric, categorical, ordinal, date/time, text, and geospatial data"}, {"id": "706cad01-5778-4dbc-8388-b5a649fb459b", "type": "concept", "title": "Entities, events, transactions, snapshots, and panels"}, {"id": "27f6f291-597e-48dd-9405-433fe5cd1712", "type": "concept", "title": "Wide versus long data"}], "description": "Students learn how business data is represented and why structure affects analysis."}, {"id": "cde62d80-71c8-43d4-8ed8-526749a56c6d", "type": "subtopic", "title": "Measurement and metric design", "children": [{"id": "89fe89df-f766-4f31-83d7-fc2bf040f272", "type": "concept", "title": "Operational definitions"}, {"id": "45ff927b-041c-46ab-889e-28c2c261169a", "type": "concept", "title": "Leading and lagging indicators"}, {"id": "13b265d2-58a8-4ede-9180-50e0218ab948", "type": "concept", "title": "Rates, ratios, denominators, and time windows"}], "description": "The point is to avoid weak metrics that distort incentives or hide the real problem."}, {"id": "4add8824-2bf7-4ad8-8b99-329b77640684", "type": "subtopic", "title": "Sampling and data-generating processes", "children": [{"id": "ace4731f-a05f-4750-aa3f-a97879843f2e", "type": "concept", "title": "Population versus sample"}, {"id": "90516c7c-fda2-4739-9334-59f02fb115b9", "type": "concept", "title": "Selection bias and survivorship bias"}, {"id": "1ddc3408-b5e1-4200-98e8-9d46ddeb0993", "type": "concept", "title": "Missing data and measurement error"}], "description": "Students learn to ask how the data came to exist before trusting it."}]}, {"id": "e4465c52-1809-434f-b61c-141f12c1e015", "type": "topic", "title": "Data Cleaning, Wrangling, and Quality Assurance", "description": "Analytics quality depends heavily on the unglamorous work of cleaning, validating, reshaping, and documenting data.", "children": [{"id": "23d8705f-26f6-47cd-b365-e13a77325bc8", "type": "subtopic", "title": "Cleaning workflows", "children": [{"id": "108c6e2c-13df-46dd-9960-0616a700ae21", "type": "concept", "title": "Missing values and duplicates"}, {"id": "288c44ce-7bbc-49ed-b0b6-eddc6b311fe1", "type": "concept", "title": "Parsing dates, categories, and identifiers"}, {"id": "87060c5c-7ddc-41d4-837e-ca8a354c89d2", "type": "concept", "title": "Outlier detection and treatment"}], "description": "Students practice turning messy data into analysis-ready data without losing auditability."}, {"id": "1d7459cf-7585-40ea-b7c1-e2852780a0d9", "type": "subtopic", "title": "Data validation", "children": [{"id": "bb7f4ba9-02b0-4de9-bf11-07c354ee5880", "type": "concept", "title": "Range checks and cross-field logic"}, {"id": "aba0c0cc-8fa0-4e53-bdce-05da065e77a9", "type": "concept", "title": "Reconciliation to source totals"}, {"id": "8dc4c2e9-100b-4243-bd85-3698fe2c8e3a", "type": "concept", "title": "Version control and data dictionaries"}], "description": "The gist is to check whether the data is plausible, complete, and internally consistent."}, {"id": "444b4434-85c2-4182-adba-3ff3f25867da", "type": "subtopic", "title": "Reproducible workflows", "children": [{"id": "efb27881-6808-43aa-8656-9acb2cc2471c", "type": "concept", "title": "Documented assumptions"}, {"id": "ec68cf7b-465b-40a4-9663-21428fd945d2", "type": "concept", "title": "Notebook or script organization"}, {"id": "bb29bfd0-845e-41ec-8907-7a7551c1f11d", "type": "concept", "title": "Repeatable imports, transformations, and exports"}], "description": "Students learn habits that let others rerun and trust the analysis."}]}, {"id": "4c14226c-bb95-478f-8355-a29379929467", "type": "topic", "title": "Spreadsheet Modeling and Analytical Thinking", "description": "Spreadsheets remain a business analytics workhorse, so students learn to build models that are clear, auditable, and decision-oriented.", "children": [{"id": "6634d0bd-6f18-4455-a6b0-3d3cffe2c546", "type": "subtopic", "title": "Model structure", "children": [{"id": "dae26cee-c8c0-40d8-bb70-4357adcbe908", "type": "concept", "title": "Assumption cells"}, {"id": "ffd0d564-8cc9-4600-99c1-08ce99423afd", "type": "concept", "title": "Helper calculations"}, {"id": "ef0fff67-3a36-4e9c-9ff8-e35a7e6c9e1f", "type": "concept", "title": "Scenario and sensitivity areas"}], "description": "Students separate inputs, calculations, outputs, and checks so models are easier to audit."}, {"id": "1a3a952b-5ef3-4ff8-aa38-0bc652f17f72", "type": "subtopic", "title": "Core spreadsheet analytics", "children": [{"id": "8031a246-41dc-4d03-9601-06d9e4d6b70a", "type": "concept", "title": "Pivot tables and aggregation"}, {"id": "b98fb1d0-6dfe-47d9-9d8e-99c073e18044", "type": "concept", "title": "Lookup and conditional logic"}, {"id": "0d197d2c-0214-42a8-be20-effea118a927", "type": "concept", "title": "Data tables and scenario manager"}], "description": "The point is to use formulas, lookup logic, pivots, and tables to answer business questions efficiently."}, {"id": "9d73801c-7ad2-4dda-90d8-88581c848dd8", "type": "subtopic", "title": "Spreadsheet risk control", "children": [{"id": "a82efca6-5c66-48e4-a8b8-c3cccde90b44", "type": "concept", "title": "Error checks and balance tests"}, {"id": "2863d688-d53a-4d92-8382-4e4962c167bd", "type": "concept", "title": "Formula consistency"}, {"id": "5d39b25d-400f-4651-aea6-ecf8c93690a2", "type": "concept", "title": "Documentation and review"}], "description": "Students learn to prevent hidden errors that can change decisions."}]}, {"id": "4182b695-73e2-4fc2-9356-0a8d04ea5a23", "type": "topic", "title": "SQL, Databases, and Business Intelligence Foundations", "description": "Students need enough database fluency to pull, join, aggregate, and interpret organizational data responsibly.", "children": [{"id": "e29a6914-a0de-4f0f-8c75-54a84c147f62", "type": "subtopic", "title": "Relational database concepts", "children": [{"id": "6ae59629-dc62-443d-979d-0a3a4ee7436d", "type": "concept", "title": "Primary keys and foreign keys"}, {"id": "747164db-dc97-4e25-b0f3-9a98c5a32c3b", "type": "concept", "title": "Fact and dimension tables"}, {"id": "20df4e93-4558-480a-bb91-c938a9942205", "type": "concept", "title": "Normalization and star schemas"}], "description": "Students learn how business entities and events are modeled in tables."}, {"id": "b4b8a492-60f2-47b8-b20a-cf2da878590e", "type": "subtopic", "title": "SQL for analytics", "children": [{"id": "3048e6c0-7eb6-4582-b131-99fc36a095d4", "type": "concept", "title": "SELECT, WHERE, GROUP BY, ORDER BY"}, {"id": "776d4baa-4653-493b-95da-fa46ba57ecbb", "type": "concept", "title": "JOINs and aggregation"}, {"id": "8ed81d86-ca45-45b5-a7c0-c5c0b4a3e0a7", "type": "concept", "title": "Window functions and common table expressions"}], "description": "The point is to retrieve the right data at the right grain."}, {"id": "842cb32a-e5da-4665-8134-273c3952d723", "type": "subtopic", "title": "BI architecture", "children": [{"id": "12ed58dd-8e5c-41dc-812d-ea49c058eef0", "type": "concept", "title": "Data warehousing and marts"}, {"id": "54f222d1-f9f7-4b3b-88b1-90d8aae11475", "type": "concept", "title": "ETL/ELT pipelines"}, {"id": "50628a41-28e5-4525-ae20-ad71892ddfd0", "type": "concept", "title": "OLAP and reporting layers"}], "description": "Students see how data warehouses, ETL/ELT, semantic models, and dashboards support decisions."}]}, {"id": "456f298d-ef4d-4f42-b6a3-8ec05a8cd80c", "type": "topic", "title": "Descriptive Analytics and Exploratory Data Analysis", "description": "This topic teaches students to summarize, compare, segment, and discover patterns before jumping to advanced models.", "children": [{"id": "3df77a26-3f80-4ffb-a0a0-3006604e0932", "type": "subtopic", "title": "Summaries and distributions", "children": [{"id": "2053b98d-1715-4940-b4a0-8ebb9462458f", "type": "concept", "title": "Counts, means, medians, percentiles, and variance"}, {"id": "d14d2d56-d5a1-4b9d-95b3-03baeb5b8c90", "type": "concept", "title": "Histograms, boxplots, and density views"}, {"id": "3c6a1fc8-a54c-4cc1-959c-af6ece76bf7d", "type": "concept", "title": "Skew, outliers, and business interpretation"}], "description": "Students learn to describe what happened with precision and context."}, {"id": "5932a53e-6078-420b-aa41-3ef341f10f6f", "type": "subtopic", "title": "Segmentation and comparison", "children": [{"id": "c27bbd5d-658f-4d91-a4bc-337f5be7e516", "type": "concept", "title": "Cohorts and segments"}, {"id": "a3dcc6e4-7d58-47bd-8f9e-95d29553d4da", "type": "concept", "title": "Cross-tabs and pivot analysis"}, {"id": "d79fdc11-d70e-4380-b319-826e493e6672", "type": "concept", "title": "Indexing and benchmarking"}], "description": "The gist is to find meaningful differences across groups, time, products, regions, and channels."}, {"id": "2595da18-2521-4222-93cd-4227b2c90737", "type": "subtopic", "title": "Exploratory workflow", "children": [{"id": "c0505ccb-81f4-48bb-b572-9f6bbead3a0f", "type": "concept", "title": "Drill-down analysis"}, {"id": "7a20d844-5383-404f-814b-66c8435a8ff4", "type": "concept", "title": "Hypothesis generation"}, {"id": "fab60c68-30b5-443d-a324-245cf8236946", "type": "concept", "title": "Avoiding overinterpretation"}], "description": "Students learn how to ask better questions as patterns emerge."}]}, {"id": "4a6cb186-1034-4b92-b3b4-a3d2003b89d8", "type": "topic", "title": "Data Visualization, Dashboards, and Storytelling", "description": "Visualization is how many analytics projects become decisions; students learn to design charts and dashboards that clarify rather than decorate.", "children": [{"id": "f8674f0b-2254-4018-b766-19826a9aaf6d", "type": "subtopic", "title": "Visualization principles", "children": [{"id": "3f963afa-28ce-453d-94e1-f4ae8ebb9507", "type": "concept", "title": "Comparison, trend, distribution, relationship, composition, and geography"}, {"id": "72dd1f92-ca78-4397-8231-651ed13cede9", "type": "concept", "title": "Pre-attentive attributes"}, {"id": "74146fe3-a024-43c5-81f4-2d3dfdf99682", "type": "concept", "title": "Color, scale, labeling, and accessibility"}], "description": "Students match chart types to analytical tasks."}, {"id": "4270d982-2fd1-4017-9673-533fcc59bd03", "type": "subtopic", "title": "Dashboard design", "children": [{"id": "78712154-3d26-4d5d-a9b0-c404e683ae8e", "type": "concept", "title": "Executive, operational, and diagnostic dashboards"}, {"id": "d375c559-246b-4205-8550-b8dd2e6efbb2", "type": "concept", "title": "KPI hierarchy and drill paths"}, {"id": "9ed976c4-f273-4036-be0d-14f4e8dae9b4", "type": "concept", "title": "Filters, context, and annotations"}], "description": "The point is to create decision interfaces, not cluttered report pages."}, {"id": "bcfdf01a-bf72-4bd4-b3f7-3940aaa2c89d", "type": "subtopic", "title": "Storytelling with data", "children": [{"id": "03e65f81-9ee4-4cab-bc72-c44359f5c43f", "type": "concept", "title": "Situation-complication-resolution"}, {"id": "ad80e2ec-0efe-4a78-9fec-b73b7c2ccb1e", "type": "concept", "title": "Narrative sequencing"}, {"id": "2ce96610-84dc-4314-97e7-7e782a609bb5", "type": "concept", "title": "Executive summaries and action framing"}], "description": "Students learn to communicate a finding, evidence, uncertainty, and recommendation."}]}, {"id": "b24a1471-c546-4f0e-b3e8-a4773182d4b8", "type": "topic", "title": "Probability, Sampling, and Statistical Inference", "description": "This unit gives students the statistical foundation for reasoning about uncertainty, variation, and evidence.", "children": [{"id": "f6d7b26d-2477-48e7-9317-83b664852736", "type": "subtopic", "title": "Probability and distributions", "children": [{"id": "3bb04806-71b5-4249-97c3-3c91daa0bf2c", "type": "concept", "title": "Random variables and expected value"}, {"id": "975710e6-0f93-413c-9afd-91f75440e913", "type": "concept", "title": "Normal, binomial, Poisson, and empirical distributions"}, {"id": "770d0200-fd40-44ef-a510-2f2755e9b818", "type": "concept", "title": "Business risk and probability thinking"}], "description": "Students learn the language of uncertainty and risk."}, {"id": "46877d2a-2093-4072-bdda-35cce3b93280", "type": "subtopic", "title": "Sampling and confidence intervals", "children": [{"id": "4aaa1473-de2d-4983-81e4-911a3a092408", "type": "concept", "title": "Central limit theorem intuition"}, {"id": "6de6c385-19ec-4c6a-b7f9-3e8babf6d4ce", "type": "concept", "title": "Standard error and margin of error"}, {"id": "3c707716-b70e-4fac-863b-dbd829385585", "type": "concept", "title": "Sample size and precision"}], "description": "The gist is to quantify how much estimates may vary from sample to sample."}, {"id": "cada5d93-7fd8-401d-aa08-90b08bd19ca3", "type": "subtopic", "title": "Hypothesis testing", "children": [{"id": "e16236ab-c2fe-4292-a039-405051171da3", "type": "concept", "title": "Null and alternative hypotheses"}, {"id": "c57c54ac-bed2-4d61-bde7-be0b8ee14dc4", "type": "concept", "title": "Type I and Type II errors"}, {"id": "a83212d3-b06a-4563-b7de-06f9f7b520b1", "type": "concept", "title": "Practical versus statistical significance"}], "description": "Students learn how to test claims without treating p-values as magic."}]}, {"id": "f2c19973-78c7-480b-961e-b199ac8f5973", "type": "topic", "title": "Regression, Forecasting, and Predictive Analytics", "description": "Students learn to model relationships and predict future outcomes while understanding assumptions, uncertainty, and limitations.", "children": [{"id": "968b47e1-7f0e-4d89-9185-53279d0794c5", "type": "subtopic", "title": "Regression foundations", "children": [{"id": "f01d7018-a84c-4b91-8bac-09f43b42bba0", "type": "concept", "title": "Simple and multiple regression"}, {"id": "543091fe-6d19-447e-a16e-28908ed1db74", "type": "concept", "title": "Dummy variables and interactions"}, {"id": "71a5a367-24bc-45ff-ab03-e016e72eb6a7", "type": "concept", "title": "Diagnostics, residuals, and confounding"}], "description": "Students use regression to estimate relationships and make controlled comparisons."}, {"id": "07c9fd5c-fcef-4553-b795-c38069ac11cf", "type": "subtopic", "title": "Forecasting methods", "children": [{"id": "b6992860-e011-48a9-b3f1-ab29b9cf3ae0", "type": "concept", "title": "Moving averages and exponential smoothing"}, {"id": "bd83609c-f749-45ea-a1ef-b5126ecddc23", "type": "concept", "title": "Trend and seasonality"}, {"id": "14705d63-9cb7-4be9-a14b-a545389309f7", "type": "concept", "title": "Forecast accuracy metrics"}], "description": "The point is to predict demand, volume, revenue, inventory, or operational load with appropriate time-series tools."}, {"id": "923b6c22-3bf9-4fc7-972e-b2d563b10706", "type": "subtopic", "title": "Predictive model evaluation", "children": [{"id": "392e42cb-ddc6-4e86-bd86-af8b51d0510a", "type": "concept", "title": "Train/test split and cross-validation"}, {"id": "1f176a10-214d-4d8c-8fd2-d49622399f1f", "type": "concept", "title": "RMSE, MAE, AUC, precision, and recall"}, {"id": "11fe501c-3c7f-4421-8fcf-22c1680f7b7b", "type": "concept", "title": "Overfitting and model selection"}], "description": "Students learn that a model is useful only if it performs on new data and supports a decision."}]}, {"id": "aefac63c-5176-45b7-b416-10224b23b347", "type": "topic", "title": "Experimentation, A/B Testing, and Causal Thinking", "description": "Business analytics should distinguish correlation from impact; this topic teaches students how to estimate whether an action caused a result.", "children": [{"id": "22cb79dc-a28b-4f62-8283-0f1df7e2a3f3", "type": "subtopic", "title": "Experiment design", "children": [{"id": "5b500c2c-9207-401c-8607-72f73c6cdc07", "type": "concept", "title": "Treatment and control groups"}, {"id": "3f6bf0cc-7d15-4ff4-8382-0609198eefb3", "type": "concept", "title": "Power and sample size"}, {"id": "c1e8f43b-df83-411a-b60a-716477a4c0fa", "type": "concept", "title": "Primary metrics and guardrail metrics"}], "description": "Students learn the logic of random assignment and controlled comparison."}, {"id": "9a1fe945-e159-4173-a294-3c2cb239233f", "type": "subtopic", "title": "A/B testing practice", "children": [{"id": "a8d39753-7e04-40b9-bba5-971cf1e1e64e", "type": "concept", "title": "Test setup and duration"}, {"id": "546368a7-dcb3-456f-84e9-a012e68a1728", "type": "concept", "title": "Multiple testing and peeking risks"}, {"id": "b1f0f60b-255f-4640-a3de-6705429a5050", "type": "concept", "title": "Lift, confidence, and rollout decisions"}], "description": "The gist is to design and interpret experiments for pricing, digital, operations, and customer experience decisions."}, {"id": "f29a489d-e30b-4dcc-9386-e00a29653e55", "type": "subtopic", "title": "Causal inference basics", "children": [{"id": "60b159af-5189-4fe2-8325-fb94a0eb73e7", "type": "concept", "title": "Confounding and omitted variables"}, {"id": "b4664b85-603b-4280-b89d-057be85ae217", "type": "concept", "title": "Difference-in-differences intuition"}, {"id": "8eb08e64-c1ee-4723-ab8e-92453610657f", "type": "concept", "title": "Matching and natural experiments"}], "description": "Students learn when experiments are not available and how observational evidence can still be improved."}]}, {"id": "b396e27c-9b8b-4799-b48e-126e80afc50d", "type": "topic", "title": "Optimization, Decision Trees, and Prescriptive Analytics", "description": "Students move from predicting outcomes to recommending actions under constraints.", "children": [{"id": "fe9d9eff-654f-41c7-96ea-acfe610d21da", "type": "subtopic", "title": "Optimization modeling", "children": [{"id": "1565e427-2f3a-4b85-ae06-30d1e9dfbb18", "type": "concept", "title": "Linear programming basics"}, {"id": "870cd541-c450-4c3b-a4fc-3204bd7c07e7", "type": "concept", "title": "Resource allocation and capacity constraints"}, {"id": "fdecd9a9-7e44-4db8-8647-de6589873413", "type": "concept", "title": "Solver interpretation and shadow prices"}], "description": "Students learn to express business choices as objectives, decision variables, and constraints."}, {"id": "889c06f1-4d0d-4793-856c-74f886ad616d", "type": "subtopic", "title": "Decision analysis", "children": [{"id": "f98458cf-6081-4b8e-9ccf-6daa613e40f0", "type": "concept", "title": "Decision trees"}, {"id": "c58c1176-024a-43eb-aad6-9ab66d983d8b", "type": "concept", "title": "Expected value and sensitivity analysis"}, {"id": "4a4390a7-512e-45a9-b06a-3e01bc06abab", "type": "concept", "title": "Value of information"}], "description": "The point is to structure uncertain choices transparently."}, {"id": "539111a7-3eda-4536-a975-619653457ea7", "type": "subtopic", "title": "Prescriptive analytics use cases", "children": [{"id": "3d600619-3bb0-475d-a13e-760cdebec2cc", "type": "concept", "title": "Product mix and scheduling"}, {"id": "1cddc6cc-5fc9-4d44-99d9-dc82f8f75a44", "type": "concept", "title": "Network and logistics decisions"}, {"id": "5090f81b-da57-4e69-87fe-8298636eed9f", "type": "concept", "title": "Inventory and procurement choices"}], "description": "Students apply models to business operations and supply chain decisions."}]}, {"id": "6cc92d84-f1b5-4f5c-a98a-891c074de7a2", "type": "topic", "title": "Simulation, Risk Analysis, and Uncertainty", "description": "Simulation helps students understand variability and risk when closed-form answers are too simple or unrealistic.", "children": [{"id": "d10ab31b-0feb-4503-9bf3-06221ac00aaa", "type": "subtopic", "title": "Monte Carlo simulation", "children": [{"id": "4e092d30-b8e6-4bcb-8286-fcded89c9f47", "type": "concept", "title": "Input distributions"}, {"id": "5f06c535-a709-4ff7-8852-79e67e59c2a9", "type": "concept", "title": "Random sampling and trials"}, {"id": "c271d85e-d919-496e-8662-217ea69e68f6", "type": "concept", "title": "Output distributions and percentiles"}], "description": "Students learn to model uncertainty with repeated random trials."}, {"id": "f18e9d3c-5bf4-407d-8009-fe85fa586a39", "type": "subtopic", "title": "Scenario and sensitivity analysis", "children": [{"id": "fc5113d1-4dc1-4e36-8444-57aaf684e4d5", "type": "concept", "title": "Best/base/worst case scenarios"}, {"id": "651df628-abf8-4981-8855-c7ebb3648275", "type": "concept", "title": "Tornado charts"}, {"id": "9ff194d7-957e-4b07-abd0-3e43220e5626", "type": "concept", "title": "Stress testing"}], "description": "The gist is to understand which assumptions matter most."}, {"id": "9027ea2b-1eec-4b2f-ac77-93e055790f81", "type": "subtopic", "title": "Risk communication", "children": [{"id": "8cd11495-2b7a-4cfc-b961-b98dc0682078", "type": "concept", "title": "Probability ranges"}, {"id": "a56b089c-d97c-4644-a324-81d5cc354ac1", "type": "concept", "title": "Decision thresholds"}, {"id": "e348f57a-168b-477e-867b-49b9201898f2", "type": "concept", "title": "Risk appetite and mitigation"}], "description": "Students learn to explain uncertainty in plain business language."}]}, {"id": "6985940e-57a5-431d-8805-9ea5c8a88e0b", "type": "topic", "title": "Machine Learning and AI for Business Analytics", "description": "This topic introduces ML and AI as tools for prediction, segmentation, automation, and decision support, with emphasis on business fit and governance.", "children": [{"id": "e89154cd-3ab3-4c7e-aa2e-650fb8bcbc36", "type": "subtopic", "title": "Supervised and unsupervised learning", "children": [{"id": "1f234b47-f4a3-4a44-abd7-eaf5d7cd94c1", "type": "concept", "title": "Classification and regression"}, {"id": "5ecae533-f391-4063-a04b-d8949ca1fcd7", "type": "concept", "title": "Clustering and segmentation"}, {"id": "9c3f89fa-ce4d-411b-8360-2e532409ef86", "type": "concept", "title": "Feature engineering and leakage"}], "description": "Students learn the basic distinction between predicting labels or values and discovering structure."}, {"id": "1a541208-ad12-4a1e-b406-9a3f9703fee9", "type": "subtopic", "title": "Business applications", "children": [{"id": "bfcfd73b-7b26-4084-bbfb-e958daf5dbaa", "type": "concept", "title": "Churn, demand, fraud, credit, and lead scoring"}, {"id": "bd9a63fb-db4e-4f69-8f12-4a8de00bca1f", "type": "concept", "title": "Recommendation and personalization"}, {"id": "eb0ace38-0fbf-403e-8b79-76a188da0791", "type": "concept", "title": "Anomaly detection and operational alerts"}], "description": "The point is to connect methods to real decisions rather than tool demos."}, {"id": "c3be7968-5d81-4219-9e74-964a59829958", "type": "subtopic", "title": "Responsible AI basics", "children": [{"id": "3cbd790a-b9d0-4bf8-a3dd-f4e1a5d151e8", "type": "concept", "title": "Bias and representativeness"}, {"id": "ebec490a-5a36-4613-9669-23fb6895080e", "type": "concept", "title": "Explainability and model documentation"}, {"id": "f8cfbfaa-7c1e-4270-bdc2-e4fd27c6eaf4", "type": "concept", "title": "Monitoring and drift"}], "description": "Students examine accuracy, fairness, explainability, privacy, and human oversight."}]}, {"id": "a7aabe5b-9478-4457-b2e4-094a9072f437", "type": "topic", "title": "Supply Chain and Operations Analytics Applications", "description": "This unit applies analytics to forecasting, inventory, logistics, service, and operations decisions within a business context.", "children": [{"id": "33e897c8-d52b-4983-9540-c5513d6bcdd6", "type": "subtopic", "title": "Demand and inventory analytics", "children": [{"id": "61134583-88c6-43e1-99a0-c8b80c9a5044", "type": "concept", "title": "Demand variability"}, {"id": "c609541a-8e98-46c3-931a-afe8cd730e11", "type": "concept", "title": "Safety stock and reorder points"}, {"id": "7a1a4e1f-81e5-4cd7-b696-2ce8202c6266", "type": "concept", "title": "Service level versus inventory cost"}], "description": "Students connect forecasting to stock decisions and service levels."}, {"id": "ca3ca022-6211-43ee-9447-cbb4132d0bab", "type": "subtopic", "title": "Logistics and network analytics", "children": [{"id": "b4dc7a65-09ef-4b0a-a37f-c02ddb8673c9", "type": "concept", "title": "Routing and transportation tradeoffs"}, {"id": "8a28b05c-1628-4e8d-a3b7-a0b3a7af672d", "type": "concept", "title": "Warehouse and network design"}, {"id": "72016bc9-cba4-4173-b4bb-bfcbf9d8c5e2", "type": "concept", "title": "Cost-to-serve analysis"}], "description": "The gist is to optimize movement, capacity, and location decisions."}, {"id": "bea6c293-369b-4184-8410-fc801336fbae", "type": "subtopic", "title": "Operations performance", "children": [{"id": "963998d6-05c9-44b4-a30c-294667b193a8", "type": "concept", "title": "Process KPIs"}, {"id": "d596198b-d86d-45af-92c5-f9f7b1c65008", "type": "concept", "title": "Queue and capacity analysis"}, {"id": "953f3ce4-2d6f-46c3-9051-04c67b0cd2e1", "type": "concept", "title": "Root cause and continuous improvement"}], "description": "Students use data to improve reliability, quality, productivity, and bottlenecks."}]}, {"id": "15115e7d-983b-4595-aa78-bd5b63126cce", "type": "topic", "title": "Analytics Ethics, Governance, and Organizational Adoption", "description": "Analytics creates value only when it is trusted, governed, and used responsibly by people and organizations.", "children": [{"id": "ecb47248-db78-4e1a-af97-f2f0be8e99b2", "type": "subtopic", "title": "Data ethics and pitfalls", "children": [{"id": "3d2f2bba-f81f-4d12-b506-196b88523ba7", "type": "concept", "title": "Privacy and consent"}, {"id": "b4ad5707-6280-4138-a23a-e81a5d1d3993", "type": "concept", "title": "Proxy variables and discrimination"}, {"id": "aad1142f-5121-4812-a628-1b7a2d6e8436", "type": "concept", "title": "Misleading visuals and metric gaming"}], "description": "Students learn how analytics can mislead or harm when incentives, data, or interpretation are flawed."}, {"id": "0a0c10ec-3f42-440d-9426-1c5706b1ddab", "type": "subtopic", "title": "Governance and quality", "children": [{"id": "e7caf977-8c5c-474f-8997-6aeda304a9ca", "type": "concept", "title": "Data ownership and stewardship"}, {"id": "94cf076a-0be7-45c5-b350-2d570401f7a4", "type": "concept", "title": "Access control and security"}, {"id": "b345f726-0991-4b4d-9cd5-c2387b255f0d", "type": "concept", "title": "Model risk management"}], "description": "The point is to create controls that support reliable analytics."}, {"id": "1347b264-4c14-4830-9a64-ede15372dca7", "type": "subtopic", "title": "Adoption and change management", "children": [{"id": "78f9dd42-3b05-48ad-960b-8b93283686d7", "type": "concept", "title": "Stakeholder mapping"}, {"id": "ae73fc93-45d6-4894-aaba-b3dcaea6c206", "type": "concept", "title": "Decision rights and incentives"}, {"id": "1c8b49c5-e0a3-447a-8499-e37ab2582167", "type": "concept", "title": "Training, documentation, and feedback"}], "description": "Students learn why the best analysis can fail if it is not usable, credible, and connected to decision routines."}]}, {"id": "f230c658-bffb-441d-8a8e-4c416dc657ba", "type": "topic", "title": "Capstone Analytics Project and Executive Recommendation", "description": "The course culminates in a complete analytics project that moves from business question to data, model, recommendation, and implementation plan.", "children": [{"id": "ca873e19-f13f-44bf-9913-529a028048d3", "type": "subtopic", "title": "Project scoping", "children": [{"id": "d635a8ec-aa50-4489-ba04-c8e985e0b252", "type": "concept", "title": "Problem statement"}, {"id": "6e76550f-fb59-4019-b766-a99d653890f8", "type": "concept", "title": "Data inventory and feasibility"}, {"id": "c0c6c5b8-7edb-45be-8a05-c81fcf37ea65", "type": "concept", "title": "Success metrics and scope boundaries"}], "description": "Students define a feasible project with a clear decision, data source, and value hypothesis."}, {"id": "039809ac-e1ec-4c76-bcda-7b89eeea8064", "type": "subtopic", "title": "Analysis execution", "children": [{"id": "06ea3cdb-9089-4f3d-9fc4-2e8af7aceacb", "type": "concept", "title": "Cleaning, visualization, modeling, and validation"}, {"id": "0ef894ab-265e-489b-abe7-0ed15ad603d5", "type": "concept", "title": "Assumptions and limitations"}, {"id": "f76855b7-b695-4f9c-9b2b-1f0a321d0f4e", "type": "concept", "title": "Reproducible files and appendix"}], "description": "The point is to demonstrate a coherent workflow using appropriate tools and methods."}, {"id": "f6f903c4-f278-46af-970b-02817e441364", "type": "subtopic", "title": "Executive recommendation", "children": [{"id": "552e2858-3ebd-4394-841c-a62e5d60d140", "type": "concept", "title": "Findings and recommendation"}, {"id": "a4a70017-c0b6-44bc-bd07-a84203f266d0", "type": "concept", "title": "Expected impact and risks"}, {"id": "e25df841-b8c0-4033-9587-ba8f9644fd78", "type": "concept", "title": "Implementation roadmap and monitoring plan"}], "description": "Students translate analysis into action for a business audience."}]}], "dbBacked": true}$badajson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'business-analytics-data-analysis'
