cription": "Analytics creates value only when it is trusted, governed, and used responsibly by people and organizations.", "children": [{"id": "ecb47248-db78-4e1a-af97-f2f0be8e99b2", "type": "subtopic", "title": "Data ethics and pitfalls", "children": [{"id": "3d2f2bba-f81f-4d12-b506-196b88523ba7", "type": "concept", "title": "Privacy and consent"}, {"id": "b4ad5707-6280-4138-a23a-e81a5d1d3993", "type": "concept", "title": "Proxy variables and discrimination"}, {"id": "aad1142f-5121-4812-a628-1b7a2d6e8436", "type": "concept", "title": "Misleading visuals and metric gaming"}], "description": "Students learn how analytics can mislead or harm when incentives, data, or interpretation are flawed."}, {"id": "0a0c10ec-3f42-440d-9426-1c5706b1ddab", "type": "subtopic", "title": "Governance and quality", "children": [{"id": "e7caf977-8c5c-474f-8997-6aeda304a9ca", "type": "concept", "title": "Data ownership and stewardship"}, {"id": "94cf076a-0be7-45c5-b350-2d570401f7a4", "type": "concept", "title": "Access control and security"}, {"id": "b345f726-0991-4b4d-9cd5-c2387b255f0d", "type": "concept", "title": "Model risk management"}], "description": "The point is to create controls that support reliable analytics."}, {"id": "1347b264-4c14-4830-9a64-ede15372dca7", "type": "subtopic", "title": "Adoption and change management", "children": [{"id": "78f9dd42-3b05-48ad-960b-8b93283686d7", "type": "concept", "title": "Stakeholder mapping"}, {"id": "ae73fc93-45d6-4894-aaba-b3dcaea6c206", "type": "concept", "title": "Decision rights and incentives"}, {"id": "1c8b49c5-e0a3-447a-8499-e37ab2582167", "type": "concept", "title": "Training, documentation, and feedback"}], "description": "Students learn why the best analysis can fail if it is not usable, credible, and connected to decision routines."}]}, {"id": "f230c658-bffb-441d-8a8e-4c416dc657ba", "type": "topic", "title": "Capstone Analytics Project and Executive Recommendation", "description": "The course culminates in a complete analytics 