  ('3bb04806-71b5-4249-97c3-3c91daa0bf2c', 'a9b0c1d2-3e4f-4a41-8b11-1c2d3e4f5a31', 'f6d7b26d-2477-48e7-9317-83b664852736', 'concept'::public.curated_course_node_type, 'Random variables and expected value', null, 0),
